def sha(value):return hashlib.sha256(value.encode()).hexdigest()
def safe(path):
 value=str(Path(path).absolute())
 return long_path(value)
def write(path,text):
 path=safe(path);path.parent.mkdir(parents=True,exist_ok=True);path.write_text(text,encoding='utf-8',newline='\n')
def adapted(body,changes):
 text=body
 for row in changes:
  i=row['index'];assert text[i:i+len(row['before'])]==row['before'],row['label']
  text=text[:i]+row['after']+text[i+len(row['before']):]
 inverse=text
 for row in changes[::-1]:
  i=row['index'];assert inverse[i:i+len(row['after'])]==row['after'],row['label']
  inverse=inverse[:i]+row['before']+inverse[i+len(row['after']):]
 assert inverse==body,'Whole original inverse failed'
 return text
